   163	int velawear_ble_init(velawear_config_t *config)
   164	{
   165	  int ret;
   166	
   167	  if (config == NULL)
   168	    {
   169	      return VELAWEAR_ERR_INVAL;
   170	    }
   171	
   172	  g_config = config;
   173	  ret = pthread_mutex_init(&g_lock, NULL);
   174	  if (ret != 0)
   175	    {
