   186	    {
   187	      pthread_mutex_destroy(&g_lock);
   188	      g_config = NULL;
   189	      syslog(LOG_WARNING, "[BLE] Bluetooth init failed: %d\n", ret);
   190	      return ret;
   191	    }
   192	
   193	  ret = bt_le_adv_start(&g_advertising_param,
   194	                        g_advertising_data, ARRAY_SIZE(g_advertising_data),
   195	                        g_scan_response_data, ARRAY_SIZE(g_scan_response_data));
   196	  if (ret < 0)
   197	    {
   198	      pthread_mutex_destroy(&g_lock);
   199	      g_config = NULL;
   200	      syslog(LOG_WARNING, "[BLE] Advertising start failed: %d\n", ret);
   201	      return ret;
   202	    }
   203	
   204	  g_initialized = true;
   205	  syslog(LOG_INFO, "[BLE] VelaWear GATT service registered; advertising\n");
   206	  return VELAWEAR_OK;
   207	}
